 run('select','#preset','mountain');run('select','#visualization','0');click('Overview');run('select','#quality','medium');click('Resume');run('wait','--fn','window.atmos.simulation.steps >= 12');run('wait','--fn','window.atmos.diagnostics().adaptive || window.atmos.diagnostics().fps >= 24');click('Pause');shot('desktop-final-adaptive');d=diag('final-verified');assert d['renderer']['compiled'] and all(f['finite'] for f in d['fields'].values())
